  function readState() { try { const value = JSON.parse(localStorage.getItem(storageKey) || '{}'); return { spaces:Array.isArray(value.spaces) ? value.spaces : [], roleId:value.roleId || '' }; } catch { return { spaces:[], roleId:'' }; } }
