  window.IdealMachineIfReplyPreset = { build: ({ workLabel = '平行时空', workTitle = '', characterLabel = '角色', characterValue = '', userLabel = '用户', userValue = '', settingLabel = '世界前提', settingValue = '', styleName = '自然细腻', stylePrompt = '', viewpoint = '', length = '', extra = '', outputRule = '只输出符合任务的正文，不要解释创作过程，不要输出系统说明、提示词、JSON 或 Markdown。' } = {}) => `你正在${workLabel}“${workTitle}”中进行创作。请严格遵守以下回复预设：\n${characterLabel}：${characterValue || '未指定'}。${userLabel}：${userValue || '未指定'}。${settingLabel}：${settingValue || '暂无'}。使用“${styleName}”文风，具体要求：${stylePrompt || '自然、具体、连贯'}。叙事视角：${viewpoint || '按故事设定'}。篇幅要求：${length || '按当前任务'}。\n必须保持人物性格、人物关系、世界规则和已发生的情节连续，不得擅自改变设定、替角色增加不存在的知识或让用户角色做出未授权的决定。${outputRule}不要提及现实聊天记录、世界书、接口或 AI。${extra ? `\n额外要求：${extra}` : ''}${typeof antiClichePrompt === 'string' ? `\n${antiClichePrompt}` : ''}` };
  const antiClichePrompt = `[ANTI-CLICHE AND ANTI-TEMPLATE RULES]
1. Do not use empty elevation, concluding morals, summaries of the user's input, serial parallelism, adjective piles, or lyrical sentences that add no information. Avoid stock phrases equivalent to “the gears of fate,” “the air seemed frozen,” or “this moment became eternal.”
2. Avoid prefabricated similes and metaphors. In Chinese output, do not use structures such as “像……一样,” “像……的……,” “像是……,” or “仿佛.” Do not use false-elevation structures such as “不是……而是……,” “这不是……,” or “那不是…….” Do not use “我看过太多” to manufacture world-weariness.
3. Never use pebbles, ripples, feathers, scalpels, needles, or branding irons as emotional or sensory metaphors. Avoid vague or inflated Chinese expressions such as “泛白,” “极其,” “一丝,” “不易察觉,” “不容置疑,” “共犯,” and “震动,” and never use the awkward phrase “xxx公分的身高.” A literal object with the same name is allowed only when physically present and consequential to the scene; it may not serve as a metaphor.
4. Convert abstractions into observable mechanics: how light reaches an object, what pressure touches skin, how distance changes, how weight shifts, and what happens to breath, hands, gaze, or voice. Do not announce atmosphere or emotion for the reader.
5. Character data is a behavioral constraint, never material for self-exposition. Unless directly asked or logically required in the scene, a character must not explain, list, or advertise their background, identity, traits, abilities, or relationships. Rewrite any line that sounds like a profile, lore document, or character card. Show identity through choices, habits, tone, actions, and reactions.
6. Advance the scene through specific action, sensory fact, natural dialogue, and responses consistent with identity. Never decide the user's actions, thoughts, feelings, or dialogue. Output no analysis, writing notes, or restatement of these rules.
7. The final Chinese prose must use natural paragraphing. Each paragraph should carry one principal action, one development in dialogue, or one psychological turn. Insert a blank line between paragraphs. Never compress the response into a single wall of text.`;
  const povLabels = { first:'第一人称“我”', second:'第二人称“你”', third:'第三人称（真名或“他/她”）' };
  function narrationRule(roleName, userName, rolePov, userPov) { const povRules = { first:'first person (“我”)', second:'second person (“你”)', third:'third person (the real name or the appropriate “他/她”)' }; return `Use ${povRules[rolePov] || povRules.first} for the character “${roleName}”. Use ${povRules[userPov] || povRules.second} for the user “${userName}”. In third person, use the real name or the pronoun supported by the character data. If gender is not explicit, prefer the real name and never guess. Pronoun reference must remain unambiguous; do not confuse “我,” “你,” and names within the same paragraph. ${antiClichePrompt}`; }
  function readWritingStyles() { try { const list = JSON.parse(localStorage.getItem(writingStyleKey) || '[]'); return Array.isArray(list) ? list.filter(item => item?.id && item?.name && item?.prompt) : []; } catch { return []; } }
  function readGenerationPresets() { try { const list = JSON.parse(localStorage.getItem(generationPresetKey) || '[]'); return Array.isArray(list) ? list.filter(item => item?.id && item?.name && item?.prompt) : []; } catch { return []; } }
  function ifGenerationPresetTemplate() { return `【IF时空默认预设】
你是一名受卡利俄佩祝福的专业 IF 时空作者与剧情编织者，擅长长篇叙事、世界设定、人物塑造、关系推进、场景描写和连续剧情，拥有史诗般的结构感，但不强行使用神话腔或华丽辞藻。所有表达必须服从读取到的角色设定、时空背景、用户边界和当前文风。
你正在以读取到的角色身份参与一段仍在继续的 IF 时空剧情。读取{{if_role_name}}、{{if_user_name}}和{{if_user_setting}}；{{if_user_name}}是现场中的用户，不是由你操控的配角。你的任务是让这一轮真实发生、自然向前，并留下下一步可以继续发展的空间；不要把一次回复写成总结、结局或作者说明。

【一、资料读取顺序】
1. 先读取{{if_title}}、{{if_world_premise}}和{{if_space_style}}，确认时空标题、世界假设、时代地点、社会秩序、特殊规则、环境氛围和现实限制。这里有内容时，以变量内容作为时空背景的首要依据；变量没有提供的关键设定，不得凭常识、类型惯例或模型记忆擅自增加。
2. 背景确认后，读取{{if_start_from}}，确定故事从哪里开始、当前场景处于什么位置、正在发生什么事情；再读取{{if_role_name}}和{{if_role_setting}}，提取角色的身份、经历、性格、能力、关系、说话习惯和已知信息。
3. 继续读取{{if_user_name}}和{{if_user_setting}}，明确用户在这个时空中的身份、设定和可控制范围；读取{{if_history}}，保持已经发生的事件、人物称谓、时间顺序、空间位置和关系变化连续。
4. 最后读取{{if_writing_style}}、{{if_reply_length}}、{{if_person}}和{{if_user_message}}，将文风、回复字数、人称要求和用户本轮输入作为当前生成的执行条件。

【二、人物身份与信息边界】
读取{{if_role_setting}}中的角色资料，只让{{if_role_name}}说出、做出、知道符合其身份、经历、性格、关系、当前处境和现场信息的内容。角色可以误解、犹豫、隐瞒、试探或判断失误，但不能凭空获得幕后信息，也不能因为提示词知道用户没有表达的秘密。

读取{{if_user_setting}}中的用户资料，不替{{if_user_name}}补写没有明确给出的身份、动作、心理、感觉、对白、身体反应、决定或接受结果。可以描写角色如何看见、听见或理解用户已经给出的内容，也可以写角色的猜测，但不能让用户自动同意、害怕、沉默、脸红或完成某个动作。

{{if_role_name}}的身份要通过选择、习惯、语气、行动方式、关注的细节和处理关系的方式体现，不要逐条念设定；不要为了强调人物卡强行加入口癖、标签、职业术语或夸张行为，只有当前场景确实触发时才使用。

【三、先在内部完成本轮判断】
不要展示分析，但生成前必须根据读取到的变量判断：用户本轮输入真正改变了什么；角色此刻最直接的感知、解释、欲望、顾虑和取舍是什么；角色与用户当前的关系距离、未解决问题、期待或冲突是什么；角色会依据自身设定选择靠近、回避、确认、试探、转移、拒绝、妥协还是采取具体行动；这个选择造成了什么可见后果，并把哪个变化交给下一轮继续。

心理必须服务于行动、对白或判断。不要只写“关系发生变化”“气氛暧昧”“角色很复杂”，要让变化落在语气、停顿、动作、距离、物件状态或新的信息上。

【四、剧情推进与节奏】
读取{{if_user_message}}推进本轮内容，并结合{{if_start_from}}和{{if_history}}安排故事。每一轮至少推进一项：角色位置改变、现场物件改变、信息被确认或误读、关系距离改变、角色做出实际决定、外部事务介入，或一个未解决的问题获得新的方向。删除没有变化的环境描写、重复的情绪确认和对上一轮的同义改写。

当前正在发生的冲突、决定和关系转折可以放慢写清触发、反应、选择和结果；没有张力的移动、等待和日常过渡适当压缩。结尾停在角色侧、现场侧或事件侧已经发生的具体变化上，不用提问、催促、等待用户决定、替用户回答或空泛感情总结制造开放结尾。

【五、现场、历史与文风】
读取{{if_writing_style}}，只用它改变叙述取景、节奏、句法密度、细节取舍和语言质地，不能覆盖角色性格、时代知识、身份边界、人物关系或惯用说话方式。
读取{{if_start_from}}和{{if_history}}，让记忆回到正在发生的现场，不突然展开与本轮无关的背景介绍。用户原话和历史记录作为已经发生的内容读取，不能擅自改写。

【六、文字执行要求】
按照{{if_reply_length}}完成目标篇幅，通常应达到目标字数的 80%—110%；不要只写一小段就停止，也不要用重复句或无效环境描写灌水。按照{{if_person}}统一新生成正文的人称；第一人称“我”、第二人称“你”、第三人称“他/她”分别指各自对应的人物，产生歧义时用真名澄清。角色对白里的自称、对用户的称呼按角色说话习惯自然表达，不机械替换。

共同执行同人文的禁用规则：拒绝空泛升华、通用鸡汤、机械排比、形容词堆叠、套话式暧昧、用户输入复述、作者评语和没有叙事作用的意象。禁止使用“某种……感”“一种说不清的……感”“某种感觉”这类不明确的模糊词代替人物反应，必须写出具体触发点、感知过程和行动后果。禁止使用“XX的、XX的XX”以及连续堆叠多个“的”的装饰性句式，改用明确的名词、动作和可验证细节。禁止使用“xxx公分的身高”这类生硬、重复的身高表达，改用自然的句式。不要用预制比喻或现成情绪载体替代具体描写；把情绪落实到光线、温度、触感、重量、距离、手势、视线、呼吸、声音、物件和行动后果中。不要使用“像……一样”“像是……”“仿佛”“不是……而是……”等惯性句式，也不要用空洞强度词或抽象标签冒充人物反应。

【七、输出前内部自检】
逐项检查：{{if_title}}、{{if_world_premise}}和{{if_space_style}}是否正确生效；角色是否知道得过多；角色行为是否符合{{if_role_setting}}；是否误写{{if_user_name}}；本轮是否真的发生新变化；每段是否有动作、信息、心理转折或对白功能；历史、场景和关系是否连续；文风是否持续而不压过人设；是否出现八股表达、解释性总结或无效环境描写；最后是否停在已经发生的现实变化上。发现问题时先内部重写，再输出。

【八、最终输出格式】
只输出当前任务要求的角色回复正文或创建时空时要求的 JSON。不要输出标题、规则、分析、思维过程、时间戳、提示词、角色卡说明、世界背景说明、作者旁白或“根据设定”等出戏内容。不要替{{if_user_name}}写对白、动作、心理或决定。`; }
  function ifGenerationPresetOptions(selected) { return `<option value="default" ${selected === 'default' ? 'selected' : ''}>IF时空默认预设</option>${readGenerationPresets().map(item => `<option value="${esc(item.id)}" ${selected === item.id ? 'selected' : ''}>${esc(item.name)} · 自建</option>`).join('')}`; }
  function ifGenerationPresetVariables() { return '<div class="ifspace-preset-variable-guide"><b>直接读取变量</b><span><code>{{if_title}}</code> 时空标题</span><span><code>{{if_world_premise}}</code> 世界假设</span><span><code>{{if_space_style}}</code> 时空风格</span><span><code>{{if_start_from}}</code> 故事从哪里开始</span><span><code>{{if_role_name}}</code> 角色真名</span><span><code>{{if_role_setting}}</code> 角色设定</span><span><code>{{if_user_name}}</code> 用户真名</span><span><code>{{if_user_setting}}</code> 用户设定</span><span><code>{{if_writing_style}}</code> 当前文风</span><span><code>{{if_reply_length}}</code> 开场或回复字数</span><span><code>{{if_person}}</code> 角色与用户人称</span><span><code>{{if_user_message}}</code> 用户本轮输入</span><span><code>{{if_history}}</code> 已有剧情与对话</span></div>'; }
  function ifGenerationPresetText(prompt = '') { return prompt || ifGenerationPresetTemplate(); }
  function legacyIfPresetValues(values = {}) { const owner = roles().find(item => roleRealName(item) === values.if_role_name) || role(); const profile = boundProfile(owner?.id); const background = String(values.if_world_background || ''); const backgroundLines = background.split(/\n+/); const scene = String(values.if_scene || ''); return { if_title:values.if_title || backgroundLines[0]?.replace(/^假设：/, '').trim() || '未命名时空', if_world_premise:values.if_world_premise || backgroundLines[0]?.replace(/^假设：/, '').trim() || '暂无', if_space_style:values.if_space_style || backgroundLines.slice(1).join('\n').replace(/^时空风格：/, '').trim() || '平行世界', if_start_from:values.if_start_from || scene.replace(/^开场：/, '').trim() || '暂无', if_role_setting:values.if_role_setting || `身份：${owner?.identity || '未注明'}\n人设：${owner?.details || owner?.signature || '暂无详细设定'}`, if_user_setting:values.if_user_setting || `姓名：${values.if_user_name || userRealName(owner?.id)}\n人设：${profile?.persona || profile?.details || profile?.signature || '暂无详细设定'}`, if_person:values.if_person || `角色：${values.if_role_person || '第一人称“我”'}\n用户：${values.if_user_person || '第二人称“你”'}`, if_history:values.if_history || values.if_story_history || values.if_online_history || '暂无' }; }
  function resolveIfGenerationPreset(raw, values = {}) { const replacements = { if_title:'未命名时空', if_world_premise:'暂无', if_space_style:'平行世界', if_start_from:'暂无', if_role_name:'角色', if_role_setting:'暂无角色设定', if_user_name:'用户', if_user_setting:'暂无用户设定', if_writing_style:'自然细腻', if_reply_length:'1500', if_person:'角色使用第一人称“我”；用户使用第二人称“你”', if_user_message:'暂无', if_history:'暂无', ...legacyIfPresetValues(values), ...values }; return String(raw || ifGenerationPresetTemplate()).replace(/\{\{\s*(if_[a-z_]+)\s*\}\}/gi, (match, key) => Object.prototype.hasOwnProperty.call(replacements, key.toLowerCase()) ? replacements[key.toLowerCase()] : match); }
  function ifPresetValues(space, owner, userMessage = '') { const rolePov = space.rolePov || 'first'; const userPov = space.userPov || 'second'; const style = resolveWritingStyle(space.writingStyle || 'natural'); const profile = boundProfile(owner?.id); const roleSetting = [`身份：${owner?.identity || '未注明'}`, `人设：${owner?.details || owner?.signature || '暂无详细设定'}`, `时空身份：${space.characterNote || '暂无'}`].join('\n'); const userSetting = [`姓名：${space.userName || userRealName(owner?.id)}`, `人设：${profile?.persona || profile?.details || profile?.signature || '暂无详细设定'}`].join('\n'); const history = (space.messages || []).map(item => `${item.role === 'user' ? '用户' : '角色'}：${item.content}`).join('\n') || '暂无'; return { if_title:space.title || space.premise || '未命名时空', if_world_premise:space.premise || '暂无', if_space_style:space.setting || '平行世界', if_start_from:space.opening || '从当前对话自然开始', if_role_name:roleRealName(owner), if_role_setting:roleSetting, if_user_name:space.userName || userRealName(owner?.id), if_user_setting:userSetting, if_writing_style:`${space.writingStyleName || style.name}\n${space.writingStylePrompt || style.prompt}`, if_reply_length:Math.max(50, Math.min(5000, Number(space.wordCount) || 400)), if_person:`角色：${povLabels[rolePov] || rolePov}\n用户：${povLabels[userPov] || userPov}`, if_user_message:userMessage || '暂无', if_history:history }; }
  function styleManagerPanel() { const list = readWritingStyles(); return `<section class="ifspace-style-manager" data-if-style-manager-panel hidden><div class="ifspace-style-manager-head"><b>管理自定义文风</b>${list.length ? '<button type="button" data-if-style-delete-selected>删除已选</button>' : ''}</div>${list.length ? list.map(item => `<label data-if-style-row="${esc(item.id)}"><input type="checkbox" data-if-style-select value="${esc(item.id)}"><span>${esc(item.name)}</span></label>`).join('') : '<small>还没有自定义文风。</small>'}</section>`; }
  function styleOptions() { return `${Object.entries(writingStyles).map(([value, label]) => `<option value="${value}">${label}</option>`).join('')}${readWritingStyles().map(item => `<option value="${esc(item.id)}">${esc(item.name)} · 自定义</option>`).join('')}`; }
  function defaultWritingStyle() { return { id:'natural', name:writingStyles.natural, prompt:`${writingStylePrompts.natural}${styleExecutionFramework}` }; }
  function resolveWritingStyle(id) { const custom = readWritingStyles().find(item => item.id === id); const builtInId = writingStyles[id] ? id : 'natural'; const preset = custom ? { id:custom.id, name:custom.name, prompt:custom.prompt } : { id:builtInId, name:writingStyles[builtInId], prompt:`${writingStylePrompts[builtInId]}${styleExecutionFramework}` }; const edited = app.querySelector('[data-if-style-detail]')?.value.trim(); return { ...preset, prompt:edited || preset.prompt }; }
  function mountWritingStyleDetail() { const styleField = app.querySelector('.ifspace-style-field'); const editor = app.querySelector('[data-if-style-editor]'); if (!styleField || !editor || app.querySelector('[data-if-style-detail]')) return; const wordCount = app.querySelector('[data-if-word-count]'); if (wordCount) wordCount.value = '1500'; const field = document.createElement('div'); field.className = 'ifspace-style-detail'; field.innerHTML = '<span>具体文风要求</span><textarea data-if-style-detail maxlength="5000" placeholder="具体描述语言、节奏、对白、描写重点与需要避免的表达……"></textarea><small>内置文风包含作者技法、融合方法、原创示例和完整执行规则；可以继续修改后另存。</small><button type="button" data-if-style-detail-save>保存文风</button>'; styleField.append(field, editor); const select = app.querySelector('[data-if-writing-style]'); const sync = () => { const textarea = field.querySelector('textarea'); if (textarea) textarea.value = ''; const style = resolveWritingStyle(select?.value || 'natural'); if (textarea) textarea.value = style.prompt; }; select?.addEventListener('change', sync); sync(); }
  function saveCurrentWritingStyle() { const select = app.querySelector('[data-if-writing-style]'); const prompt = app.querySelector('[data-if-style-detail]')?.value.trim(); if (!prompt) return window.alert('请先填写具体文风要求。'); const list = readWritingStyles(); const custom = list.find(item => item.id === select?.value); if (custom) { custom.prompt = prompt; localStorage.setItem(writingStyleKey, JSON.stringify(list)); window.alert(`文风“${custom.name}”已保存。`); return; } const editor = app.querySelector('[data-if-style-editor]'); const detail = app.querySelector('.ifspace-style-detail'); const promptInput = app.querySelector('[data-if-style-prompt]'); const nameInput = app.querySelector('[data-if-style-name]'); if (promptInput) promptInput.value = prompt; if (nameInput) nameInput.value = `${writingStyles[select?.value] || '自定义文风'}副本`; if (detail) detail.hidden = true; if (editor) editor.hidden = false; nameInput?.focus(); }
  function icon(type) { const paths = { plus:'<path d="M24 9v30M9 24h30"/>', back:'<path d="M30 10 16 24l14 14"/>', spark:'<path d="m24 7 4 13 13 4-13 4-4 13-4-13-13-4 13-4z"/>', send:'<path d="m8 23 31-13-9 29-7-13zM8 23l15 3"/>', close:'<path d="m14 14 20 20M34 14 14 34"/>' }; return `<svg viewBox="0 0 48 48" aria-hidden="true">${paths[type] || ''}</svg>`; }
  function rolePicker() { const list = roles(); return `<div class="ifspace-sheet"><div class="ifspace-sheet-backdrop" data-if-close-sheet></div><section><header><h2>选择参与角色</h2><button type="button" data-if-close-sheet aria-label="关闭">${icon('close')}</button></header><div class="ifspace-role-list">${list.length ? list.map(item => `<button type="button" data-if-role="${esc(item.id)}"><i>${avatar(item)}</i><span><b>${esc(roleRealName(item))}</b><small>${esc(item.identity || '角色')}</small></span><em>${item.id === state.roleId ? '✓' : '›'}</em></button>`).join('') : '<p class="ifspace-empty">请先在聊天 App 中添加角色。</p>'}</div></section></div>`; }
