  document.addEventListener('click', event => { if (event.target.closest('[data-app-key="ifshikong"]')) { state=readState(); page='home'; activeId=''; managingSpaces=false; render(); app.classList.add('is-open'); return; } if (!app.classList.contains('is-open')) return; if (event.target.closest('[data-if-close]')) { app.classList.remove('is-open'); return; } if (event.target.closest('[data-if-new]')) { managingSpaces=false; page='create'; render(); return; } if (event.target.closest('[data-if-random]')) { randomizeWorld(); return; } if (event.target.closest('[data-if-home]')) { managingSpaces=false; page='home'; activeId=''; render(); return; } if (event.target.closest('[data-if-role-picker]')) { page='role-picker'; render(); return; } if (event.target.closest('[data-if-close-sheet]')) { page='home'; render(); return; } const selectedRole=event.target.closest('[data-if-role]'); if(selectedRole){state.roleId=selectedRole.dataset.ifRole;save();page='home';render();return;} if (event.target.closest('[data-if-space-manage]')) { managingSpaces=!managingSpaces; render(); return; } if (event.target.closest('[data-if-space-delete-selected]')) { const ids=[...app.querySelectorAll('[data-if-space-select]:checked')].map(input=>input.value); if (!ids.length) return window.alert('请先选择要删除的宇宙。'); if (!window.confirm(`确定删除选中的 ${ids.length} 个宇宙吗？`)) return; state.spaces=state.spaces.filter(item=>!ids.includes(item.id)); managingSpaces=false; save(); page='home'; activeId=''; render(); return; } const opened=event.target.closest('[data-if-open]'); if(opened){activeId=opened.dataset.ifOpen;managingSpaces=false;page='detail';render();return;} const deleted=event.target.closest('[data-if-delete]'); if(deleted){state.spaces=state.spaces.filter(item=>item.id!==deleted.dataset.ifDelete);save();page='home';activeId='';render();return;} if(event.target.closest('[data-if-create]')){createSpace();return;} });
